//
// What the client writes of what it does, through the caller's logger (the console by default):
// at `info` one line per attempt, at `debug` the request's URL and headers too. Secrets never
// reach it: the headers that carry credentials (the usual ones, and those the description's
// security schemes name) and the query parameters its API keys go in are written as `***`, and a
// URL loses its user, its password and its fragment.

import { type Logger, platform, readEnv } from "./platform.js";

/** How much the client writes: `off`, then each level writes what the ones before it do. */
export type LogLevel = "off" | "error" | "warn" | "info" | "debug";

const LEVELS: { readonly [level in LogLevel]: number } = { off: 0, error: 1, warn: 2, info: 3, debug: 4 };

/** Headers that carry credentials whatever the description says. */
const SECRET_HEADERS = ["authorization", "proxy-authorization", "api-key", "x-api-key", "cookie", "set-cookie", "x-amz-security-token"];

function isLevel(value: string): value is LogLevel {
  return Object.prototype.hasOwnProperty.call(LEVELS, value);
}

const silent = (): void => {};

/** The logger at a level: the option's, else the environment variable's (a value that is no level
 * is warned about and passed over), else `warn`. Methods above the level do nothing. */
export function makeLogger(option: LogLevel | undefined, env: string, given: Logger | undefined): Logger {
  const logger = given ?? platform().console ?? { error: silent, warn: silent, info: silent, debug: silent };
  let level: LogLevel = "warn";
  if (option !== undefined) {
    level = option;
  } else {
    const value = readEnv(env)?.toLowerCase();
    if (value !== undefined && isLevel(value)) level = value;
    else if (value !== undefined) logger.warn(`${env} is ${JSON.stringify(value)}, not one of off, error, warn, info, debug: left at warn`);
  }
  const at = LEVELS[level];
  const pick = (n: number, f: Logger["error"]): Logger["error"] => (n <= at ? f.bind(logger) : silent);
  return {
    error: pick(1, logger.error),
    warn: pick(2, logger.warn),
    info: pick(3, logger.info),
    debug: pick(4, logger.debug),
  };
}

/** Where secrets go, by name: headers in lower case, query parameters as written. */
export type Secrets = { readonly headers: ReadonlySet<string>; readonly query: ReadonlySet<string> };

/** The secrets of the description's security schemes, with the usual headers. */
export function secretsOf(schemes: { readonly [name: string]: { readonly type: string; readonly in?: string; readonly name?: string } }): Secrets {
  const headers = new Set(SECRET_HEADERS);
  const query = new Set<string>();
  for (const s of Object.values(schemes)) {
    if (s.type !== "apiKey" || s.name === undefined) continue;
    if (s.in === "header") headers.add(s.name.toLowerCase());
    if (s.in === "query") query.add(s.name);
  }
  return { headers, query };
}

/** Headers as written to the log: a secret's value `***`. */
export function maskHeaders(headers: Record<string, string>, secrets: Secrets): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [name, value] of Object.entries(headers)) out[name] = secrets.headers.has(name.toLowerCase()) ? "***" : value;
  return out;
}

/** A URL as written to the log: no user, password or fragment, a secret parameter's value `***`. */
export function redactURL(url: string, secrets: Secrets): string {
  let out = url.replace(/^([a-z][a-z0-9+.-]*:\/\/)[^/?#@]*@/i, "$1");
  const hash = out.indexOf("#");
  if (hash >= 0) out = out.slice(0, hash);
  const q = out.indexOf("?");
  if (q < 0 || secrets.query.size === 0) return out;
  const pairs = out.slice(q + 1).split("&").map((pair) => {
    const eq = pair.indexOf("=");
    const key = eq < 0 ? pair : pair.slice(0, eq);
    let name = key;
    try {
      name = decodeURIComponent(key.replace(/\+/g, " "));
    } catch {
      name = key;
    }
    return secrets.query.has(name) ? `${key}=***` : pair;
  });
  return out.slice(0, q + 1) + pairs.join("&");
}
